@push('scripts')<script>const q=document.getElementById('orderSearch'),s=document.getElementById('statusFilter');function filterOrders(){document.querySelectorAll('#ordersTable tbody tr[data-status]').forEach(r=>r.hidden=!(r.innerText.toLowerCase().includes(q.value.toLowerCase())&&(!s.value||r.dataset.status===s.value)))}q?.addEventListener('input',filterOrders);s?.addEventListener('change',filterOrders)</script>@endpush
